// Simple Asteroid Evader game
// Canvas with id "game" must exist in the HTML

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // Ship definition
  const ship = {
    x: width / 2,
    y: height / 2,
    vx: 0,
    vy: 0,
    angle: 0, // radians
    radius: 12,
    thrust: 0.1,
    rotateSpeed: 0.07,
    draw() {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.angle);
      ctx.beginPath();
      ctx.moveTo(0, -this.radius);
      ctx.lineTo(this.radius, this.radius);
      ctx.lineTo(-this.radius, this.radius);
      ctx.closePath();
      ctx.fillStyle = '#0f0';
      ctx.fill();
      ctx.restore();
    },
    update() {
      this.x += this.vx;
      this.y += this.vy;
      // screen wrap
      if (this.x < 0) this.x += width;
      if (this.x > width) this.x -= width;
      if (this.y < 0) this.y += height;
      if (this.y > height) this.y -= height;
    }
  };

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.code] = true; });
  window.addEventListener('keyup', e => { keys[e.code] = false; });

  // Asteroid definition
  const asteroids = [];
  const asteroidConfig = {
    minRadius: 15,
    maxRadius: 30,
    minSpeed: 0.5,
    maxSpeed: 2.0,
    spawnInterval: 2000 // ms
  };

  function randomBetween(min, max) {
    return Math.random() * (max - min) + min;
  }

  function spawnAsteroid() {
    const radius = randomBetween(asteroidConfig.minRadius, asteroidConfig.maxRadius);
    // Choose a random edge
    const edge = Math.floor(Math.random() * 4);
    let x, y, vx, vy;
    switch (edge) {
      case 0: // top
        x = randomBetween(0, width);
        y = -radius;
        break;
      case 1: // right
        x = width + radius;
        y = randomBetween(0, height);
        break;
      case 2: // bottom
        x = randomBetween(0, width);
        y = height + radius;
        break;
      case 3: // left
        x = -radius;
        y = randomBetween(0, height);
        break;
    }
    const angle = Math.atan2(height / 2 - y, width / 2 - x);
    const speed = randomBetween(asteroidConfig.minSpeed, asteroidConfig.maxSpeed);
    vx = Math.cos(angle) * speed;
    vy = Math.sin(angle) * speed;
    asteroids.push({ x, y, vx, vy, radius, angle: 0 });
  }

  // Game state
  let lastTime = performance.now();
  let accumulator = 0;
  let gameOver = false;
  let score = 0;

  function update(dt) {
    if (gameOver) return;
    // Input
    if (keys['ArrowLeft']) ship.angle -= ship.rotateSpeed;
    if (keys['ArrowRight']) ship.angle += ship.rotateSpeed;
    if (keys['ArrowUp'] || keys['Space']) {
      ship.vx += Math.cos(ship.angle) * ship.thrust;
      ship.vy += Math.sin(ship.angle) * ship.thrust;
    }
    // Apply friction
    ship.vx *= 0.99;
    ship.vy *= 0.99;

    ship.update();

    // Update asteroids
    for (const a of asteroids) {
      a.x += a.vx;
      a.y += a.vy;
      // wrap
      if (a.x < -a.radius) a.x += width + a.radius * 2;
      if (a.x > width + a.radius) a.x -= width + a.radius * 2;
      if (a.y < -a.radius) a.y += height + a.radius * 2;
      if (a.y > height + a.radius) a.y -= height + a.radius * 2;
    }

    // Collision detection (circle vs ship point)
    for (const a of asteroids) {
      const dx = ship.x - a.x;
      const dy = ship.y - a.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.radius) {
        gameOver = true;
        break;
      }
    }

    // Score based on survival time
    score += dt / 1000;
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw ship
    ship.draw();
    // Draw asteroids
    ctx.fillStyle = '#888';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // Draw score
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#f00';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    accumulator += dt;
    while (accumulator >= 16) { // ~60fps fixed step
      update(16);
      accumulator -= 16;
    }
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Start spawning asteroids
  spawnAsteroid();
  setInterval(spawnAsteroid, asteroidConfig.spawnInterval);

  requestAnimationFrame(loop);
})();
